public class SomeClass {

    @Override
    public BaseObject remove(int index) {
        rangeCheck(index);
        BaseObject previous = this.map.remove(index);
        if (index < this.size - 1) {
            for (int i = index; i < this.size - 1; ++i) {
                put(i, get(i + 1));
            }
        }
        --this.size;
        return previous;
    }
}

