                e = e.split(" ")[0];
            }
            return MessageFormat.format("({0} >= ''{1}'' and {0} <= ''{2}'')", categoryField.getName(), s, e);
        } else {
            return String.format("%s = '%s'", categoryField.getName(), value);
        }
    }
