        if (selectionWithContainer) {
            if (leafs.isEmpty()) {
                wControl.setError(getTranslator().translate("send.mail.noFileSelected"));
                return null;
            } else {
                setFormWarning(getTranslator().translate("send.mail.selectionContainsFolder"));
            }
        }
        setFiles(rootContainer, leafs);
        return this;
    }
}

