            if (vanityUrl == null || VanityUrlAPI.CACHE_404_VANITY_URL.equals(vanityUrl.getVanityUrlId()) || (!InodeUtils.isSet(vanityUrl.getVanityUrlId()) && !UtilMethods.isSet(vanityUrl.getForwardTo()))) {
