    public void uploadImage(@RequestParam MultipartFile[] upload) {
        String callback = request.getParameter("CKEditorFuncNum");
        PrintWriter out = null;
        try {
            response.setCharacterEncoding("utf-8");
            out = response.getWriter();
        } catch (IOException e) {
            e.printStackTrace();
        }
