            Boolean bAjax = (Boolean) context.get("ajax");
            if ((bAjax == null) || (!bAjax.booleanValue())) {
                String continueToURL = getContinueToURL(request);
                response.sendRedirect(response.encodeRedirectURL(continueToURL));
            }
        } else {
